mapper.select:
SELECT * FROM uphoto 
WHERE uphoto_status = 1 AND uphoto_review_status = 2 
AND CASE #{label_index} 
    WHEN 0 THEN uphoto_label_0 = #{label_value}
    WHEN 1 THEN uphoto_label_1 = #{label_value}
    WHEN 2 THEN uphoto_label_2 = #{label_value}
    WHEN 3 THEN uphoto_label_3 = #{label_value}
    WHEN 4 THEN uphoto_label_4 = #{label_value}
    WHEN 5 THEN uphoto_label_5 = #{label_value}
    WHEN 6 THEN uphoto_label_6 = #{label_value}
    WHEN 7 THEN uphoto_label_7 = #{label_value}
    WHEN 8 THEN uphoto_label_8 = #{label_value}
    WHEN 9 THEN uphoto_label_9 = #{label_value}
END
ORDER BY created_at DESC
